CREATE OR REPLACE FUNCTION public.spar_may(p_world uuid, g creature, s creature, p_x integer, p_y integer)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
AS $function$
begin
  if g.world_id <> p_world or g.id = s.id or g.mode <> 'deed' or g.post is not null or g.keeper is distinct from s.keeper
     or g.enemy is not null or g.phase in ('rest', 'bed') or g.worn >= tire_of(g)
     or (g.spar_with is not null and g.spar_with <> s.id) then
